import styled from '@emotion/styled';

export const StyledSearchResultsContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '24px',
  paddingBottom: '24px',
});

export const StyledSearchResults = styled.div({
  display: 'grid',
  gridTemplateColumns: 'repeat(5, 1fr)',
  width: '100%',
  gap: '24px',
  paddingBottom: '24px',
  flexDirection: 'column',
});

export const StyledTotalResultsContainer = styled.div({
  display: 'flex',
  flexDirection: 'row',
  gap: '4px',
  textAlign: 'left',
  color: '#67665F',
  fontFamily: 'Work Sans',
  fontSize: '16px',
  lineHeight: '140%',
});

export const StyledTotalResults = styled.span({
  fontWeight: 700,
  fontStyle: 'Bold',
});
